function qrSvg(url) {
  const matrix=qrMatrix(url), paths=[];
  matrix.forEach((row,y)=>row.forEach((v,x)=>{if(v) paths.push(`M${x+4} ${y+4}h1v1h-1z`);}));
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 49 49" role="img" aria-label="QR ตรวจสอบเอกสาร"><path fill="white" d="M0 0h49v49H0z"/><path fill="black" d="${paths.join('')}"/></svg>`;
}

function pdf(doc,serviceName,url) {
  const objects=[];
  const add=value=>{objects.push(Buffer.isBuffer(value)?value:Buffer.from(value,'utf8'));return objects.length;};
  const stream=(dict,b)=>Buffer.concat([Buffer.from(`<< ${dict} /Length ${b.length} >>\nstream\n`),b,Buffer.from('\nendstream')]);
  add('<< /Type /Catalog /Pages 2 0 R >>');
  add('<< /Type /Pages /Kids [3 0 R] /Count 1 >>');
  add('<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 5 0 R >> >> /Contents 4 0 R >>');
  const text=(s,x,y,size=14)=>{
    const glyphs=Array.from(s).map(c=>(FONT_MAP[c.codePointAt(0)] || FONT_MAP[63])[0].toString(16).padStart(4,'0')).join('');
    return `BT /F1 ${size} Tf 1 0 0 1 ${x} ${y} Tm <${glyphs}> Tj ET\n`;
  };
  let content=text('เทศบาลนครตัวอย่าง',48,790,22)+text('เอกสารดิจิทัล · ระบบจำลอง',48,758,18);
  const lines=[`เลขเอกสาร: ${doc.docNo}`,`เลขคำขอ: ${doc.caseNo}`,`ชื่อผู้ยื่น: ${doc.applicant}`,
    `บริการ: ${doc.serviceId} ${serviceName}`,`วันออก: ${T.fmtThai(doc.issuedAt)}`,
    `ใช้ได้ถึง: ${T.fmtThaiDate(doc.validUntil)}`,`ผู้ลงนาม: ${doc.signer}`,`รหัสตรวจสอบ: ${doc.verifyCode}`];
  lines.forEach((line,i)=>{content+=text(line,48,714-i*30);});
  content+=text(url,48,238,10);
  const qr=qrMatrix(url), scale=3;
  content+='0 g\n';qr.forEach((row,y)=>row.forEach((v,x)=>{if(v)content+=`${48+(x+4)*scale} ${270+(44-y)*scale} ${scale} ${scale} re f\n`;}));
  // ASCII contract record is deliberately uncompressed and outside text encoding.
  content+=`% docNo=${doc.docNo} caseNo=${doc.caseNo} verify=${doc.verifyCode} validUntil=${doc.validUntil}\n`;
  add(stream('',Buffer.from(content)));
  add('<< /Type /Font /Subtype /Type0 /BaseFont /FreeSerif /Encoding /Identity-H /DescendantFonts [6 0 R] /ToUnicode 9 0 R >>');
  const widths=Object.values(FONT_MAP).map(([g,w])=>`${g} [${w}]`).join(' ');
  add(`<< /Type /Font /Subtype /CIDFontType2 /BaseFont /FreeSerif /CIDSystemInfo << /Registry (Adobe) /Ordering (Identity) /Supplement 0 >> /FontDescriptor 7 0 R /CIDToGIDMap /Identity /DW 1000 /W [${widths}] >>`);
  add('<< /Type /FontDescriptor /FontName /FreeSerif /Flags 4 /FontBBox [-1000 -500 2000 1500] /ItalicAngle 0 /Ascent 900 /Descent -300 /CapHeight 700 /StemV 80 /FontFile2 8 0 R >>');
  const font=Buffer.from(FONT_DATA,'base64');
  add(stream(`/Filter /FlateDecode /Length1 ${zlib.inflateSync(font).length}`,font));
  const mappings=Object.entries(FONT_MAP).map(([cp,[g]])=>`<${g.toString(16).padStart(4,'0')}> <${Number(cp).toString(16).padStart(4,'0')}>`);
  let cmap='/CIDInit /ProcSet findresource begin\n12 dict begin\nbegincmap\n/CIDSystemInfo << /Registry (Adobe) /Ordering (UCS) /Supplement 0 >> def\n/CMapName /Adobe-Identity-UCS def\n/CMapType 2 def\n1 begincodespacerange\n<0000> <FFFF>\nendcodespacerange\n';
  for(let i=0;i<mappings.length;i+=100){const part=mappings.slice(i,i+100);cmap+=`${part.length} beginbfchar\n${part.join('\n')}\nendbfchar\n`;}
  cmap+='endcmap\nCMapName currentdict /CMap defineresource pop\nend\nend';add(stream('',Buffer.from(cmap)));
  const chunks=[Buffer.from('%PDF-1.4\n%\xE2\xE3\xCF\xD3\n','binary')],offsets=[0];let length=chunks[0].length;
  objects.forEach((object,i)=>{offsets.push(length);const chunk=Buffer.concat([Buffer.from(`${i+1} 0 obj\n`),object,Buffer.from('\nendobj\n')]);chunks.push(chunk);length+=chunk.length;});
  chunks.push(Buffer.from(`xref\n0 ${objects.length+1}\n0000000000 65535 f \n${offsets.slice(1).map(n=>String(n).padStart(10,'0')+' 00000 n \n').join('')}trailer\n<< /Size ${objects.length+1} /Root 1 0 R >>\nstartxref\n${length}\n%%EOF\n`));
  return Buffer.concat(chunks);
}
function mount(app) {
  app.post('/api/officer/cases/:caseNo/issue',auth.requireRole('officer'),(req,res)=>{
    const result=issue(req.params.caseNo,req.user);
    if(result.error) return fail(res,result.error,result.code);
    res.json(result);
  });
  app.get('/api/documents/:docNo/pdf',auth.requireLogin,(req,res)=>{
    const row=db.prepare('SELECT d.*,c.citizen_id,s.name AS service_name FROM documents d JOIN cases c ON c.case_no=d.case_no LEFT JOIN services s ON s.id=d.service_id WHERE d.doc_no=?').get(req.params.docNo);
    const u=req.user;
    if(!row || !(['officer','head'].includes(u.role) || (u.role==='citizen' && row.citizen_id===u.citizenId))) return fail(res,404,'NOT_FOUND');
    const url=`${req.protocol}://${req.get('host')}/verify/${row.verify_code}`;
    res.type('application/pdf').set('Content-Disposition',`attachment; filename="${row.doc_no}.pdf"`).set('Cache-Control','private, no-store').send(pdf(fromRow(row),row.service_name || '',url));
  });
  app.get('/api/verify/:code',(req,res)=>{
    const result=verify(req.params.code);res.set('Cache-Control','no-store').status(result.result==='NOT_FOUND'?404:200).json(result);
  });
  app.get('/verify/:code',(req,res)=>{
    const r=verify(req.params.code), labels={VALID:'เอกสารถูกต้อง',EXPIRED:'เอกสารหมดอายุ',TAMPERED:'ลายเซ็นไม่ถูกต้อง',NOT_FOUND:'ไม่พบเอกสาร'};
    let details='';
    if(r.result==='VALID'||r.result==='EXPIRED') {
      const service=db.prepare('SELECT name FROM services WHERE id=?').get(r.serviceId);
      const field=(id,label,value,iso)=>`<dt>${esc(label)}</dt><dd data-testid="verify-${id}"${iso?` data-iso="${esc(iso)}"`:''}>${esc(value)}</dd>`;
      details='<dl>'+field('doc-no','เลขเอกสาร',r.docNo)+field('applicant','ผู้ยื่น',r.applicantMasked)+field('service','บริการ',`${r.serviceId} ${service?service.name:''}`)
        +field('issued','วันออก',T.fmtThai(r.issuedAt),r.issuedAt)+field('expires','ใช้ได้ถึง',T.fmtThaiDate(r.validUntil),r.validUntil)+field('signer','ผู้ลงนาม',r.signer)+'</dl>';
    }
    res.set('Cache-Control','no-store').status(r.result==='NOT_FOUND'?404:200).type('html').send(`<!doctype html><html lang="th"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>ตรวจสอบเอกสาร · เทศบาลนครตัวอย่าง</title><style>*{box-sizing:border-box}body{margin:0;background:#f4f7fa;color:#172b41;font:17px/1.7 system-ui,sans-serif}main{max-width:760px;margin:32px auto;padding:24px;background:white;border:1px solid #ccd5df;border-radius:12px;overflow-wrap:anywhere}h1{font-size:1.6rem}h2{font-size:1.2rem}dt{font-weight:700;margin-top:14px}dd{margin-left:0}@media(max-width:600px){main{margin:12px;padding:18px}}</style></head><body><main><h1>ตรวจสอบเอกสารดิจิทัล</h1><p>เทศบาลนครตัวอย่าง · ระบบจำลอง</p><h2 data-testid="verify-result" data-result="${r.result}">${labels[r.result]}</h2>${details}</main></body></html>`);
  });
  app.post('/api/test/documents/:docNo/tamper',(req,res)=>{
    if(!cfg.TEST_MODE) return fail(res,404,'NOT_FOUND');
    const change=db.prepare("UPDATE documents SET applicant=applicant || ' (แก้ไข)' WHERE doc_no=?").run(req.params.docNo);
    if(!change.changes) return fail(res,404,'NOT_FOUND');res.json({ok:true});
  });
}
module.exports=mount;
Object.assign(module.exports,{validUntil,maskName,verify,issue,pdf,qrMatrix,qrSvg});

